"""E-PM1 tasks, part A: finance scopes (payables, receivables, compliance) and people/members.
Each task: masked request (requester's words, no trigger phrase), verbatim request (contains a trigger; used only in
the free routing analysis), its own records, the gold procedure's checklist (S) and outcome assertions (O)."""
from world_common import (R, S, O, call, none, any_, all_, final, re, re_all, ne, num, tagnote)


def T(id, gold, scope, business, frm, masked, verbatim, records, steps, outcomes):
    return dict(id=id, gold=gold, scope=scope, business=business, frm=frm, masked=masked, verbatim=verbatim,
                records=records, steps=steps, outcomes=outcomes)


